function performanceTool(config2) {
  return {
    name: config2.name,
    title: config2.title,
    description: config2.description,
    inputSchema: {
      customerId: CustomerIdInput,
      ...dateRangeShape,
      campaignIds: external_exports.array(NumericIdInput).max(200).optional(),
      ...config2.resource === "ad_group" ? { adGroupIds: external_exports.array(NumericIdInput).max(200).optional() } : {},
      segments: external_exports.array(external_exports.enum(["date", "week", "month", "device", "network"])).max(2).optional(),
      orderBy: external_exports.enum(["cost", "clicks", "impressions", "conversions", "ctr"]).optional(),
      limit: external_exports.number().int().min(1).max(1e3).optional(),
      pageToken: external_exports.string().min(1).optional()
    },
    outputSchema: {
      customerId: external_exports.string(),
      dateRange: external_exports.record(external_exports.string(), external_exports.unknown()),
      segments: external_exports.array(external_exports.string()),
      rows: external_exports.array(external_exports.record(external_exports.string(), external_exports.unknown())),
      totals: external_exports.record(external_exports.string(), external_exports.unknown()),
      rowCount: external_exports.number(),
      nextPageToken: external_exports.string().optional(),
      message: external_exports.string()
    },
    async handler(deps2, input) {
      const customerId = input.customerId;
      const range = resolveDateRange(input);
      const limit = input.limit ?? deps2.config.reads.defaultRowLimit;
      const segments = input.segments ?? [];
      const orderBy = input.orderBy ?? "cost";
      const filters = [range.clause, `${config2.resource}.status != 'REMOVED'`];
      const campaignIds = input.campaignIds;
      if (campaignIds && campaignIds.length > 0) {
        filters.push(`campaign.id IN (${gaqlIdList(campaignIds)})`);
      }
      const adGroupIds = input.adGroupIds;
      if (adGroupIds && adGroupIds.length > 0) {
        filters.push(`ad_group.id IN (${gaqlIdList(adGroupIds)})`);
      }
      const segmentFields = segments.map((s2) => SEGMENT_FIELDS[s2]).filter(Boolean);
      const select = [...config2.identityFields, ...segmentFields, ...METRIC_FIELDS].join(", ");
      const query = `SELECT ${select} FROM ${config2.resource} WHERE ${filters.join(" AND ")} ORDER BY ${ORDER_BY_FIELDS[orderBy] ?? "metrics.cost_micros"} DESC LIMIT ${limit}`;
      const page = await deps2.transport.search(
        {
          customerId,
          query,
          ...typeof input.pageToken === "string" && { pageToken: input.pageToken }
        },
        { label: config2.name }
      );
      const rows = page.results.map((row) => ({
        ...config2.mapRow(row),
        ...segments.length > 0 && { segments: mapSegments(row, segments) },
        metrics: mapMetrics(row)
      }));
      const totals = totalMetrics(rows.map((r2) => r2.metrics));
      return {
        customerId,
        dateRange: { preset: range.preset ?? null, startDate: range.startDate ?? null, endDate: range.endDate ?? null },
        segments,
        rows,
        totals,
        rowCount: rows.length,
        ...page.nextPageToken !== void 0 && { nextPageToken: page.nextPageToken },
        message: `${rows.length} row(s); ${totals.clicks} clicks and ${formatMicros(BigInt(totals.costMicros))} total spend.`
      };
    }
  };
}
